import {ENEMIES,ENEMY_IDS} from './enemy-roster.mjs';
import {EnemyPainter,loadEnemyAssets} from './enemy-painter.mjs';
import {STAGES} from './campaign-data.mjs';
import {enemyPortraitStyle} from './campaign-enemy-ui.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],canvas=$('#beast-preview'),ctx=canvas.getContext('2d'),assets={};
let category='normal',selected='M01',motion='idle',face=1,painter=new EnemyPainter(ctx,assets),token=0,time=0,last=performance.now(),entity=null,world=null;
const role=id=>ENEMIES[id].boss?'近战 / 远程 / 连招':ENEMIES[id].ranged?'远程':id==='M10'?'近战 / 远程':'近战';
function list(){const ids=ENEMY_IDS.filter(id=>ENEMIES[id].boss===(category==='boss'));$('#category-note').textContent=category==='boss'?'变异妖兽即守关 BOSS · 11 位首领':'普通妖兽 · 6 种近战 / 3 种远程 / 1 种混合';$('#beast-list').innerHTML=ids.map(id=>`<button class="beast-entry" data-beast="${id}" aria-pressed="${id===selected}"><i aria-hidden="true" style="${enemyPortraitStyle(id)}"></i><span><strong>${ENEMIES[id].name}</strong><small>${role(id)}</small></span></button>`).join('');$$('[data-beast]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.beast)));$$('[data-kind]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.kind===category)));}
async function choose(id){
 selected=id;const d=ENEMIES[id],current=++token;motion='idle';time=0;entity=null;list();$('#beast-kind').textContent=d.boss?'变异妖兽 · 守关首领':'普通妖兽';$('#beast-name').textContent=d.name;$('#base-health').textContent=d.hp;$('#combat-role').textContent=role(id);$('#trait-name').textContent=d.boss?'被动 · '+d.passive:'妖兽特点';$('#trait-copy').textContent=d.passiveText||d.trait||(d.ranged?'保持距离寻找出手机会，弹体与施法预警清楚可辨。':id==='M03'?'可飞行追击，收翼后俯冲撕咬。':id==='M10'?'近身钩斧连击与远程锁链交替施压。':'追击玩家，近身攻击有蓄力、有效期与收招，受击会出现短暂硬直。');
 $('#moves').innerHTML=d.patterns.map(p=>`<li><b>${p.name}<i>${({melee:'近战',range:'远程',special:'主动'})[p.kind]||'技能'}</i></b>${p.steps.map(s=>s.name).join(' → ')}</li>`).join('');const stages=STAGES.filter(s=>s.boss===id||s.melee===id||s.ranged===id);$('#appearances').innerHTML=stages.map(s=>`<div><span>第${s.id}关 · ${s.name}</span><b>${d.boss?s.bossHp:s.minionHp+' / '+(s.minionHp+3)+' / '+(s.minionHp+6)} 生命</b></div>`).join('');$('#beast-trial').href='enemies.html?enemy='+id;
 $$('[data-motion]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.motion==='idle'));b.disabled=!['idle','walk'].includes(b.dataset.motion)&&!d.patterns.some(p=>p.kind===b.dataset.motion);});$('#load-notice').textContent='正在载入独立动作…';
 try{await loadEnemyAssets([id],assets);if(current!==token)return;entity={id:'bestiary',enemyKind:id,x:340,y:480,prevX:340,prevY:480,w:d.w,h:d.h,visual:d.boss?310:250,hp:d.hp,maxHp:d.hp,face,vx:0,vy:0,cycle:0,grounded:true,hit:0,scale:1,ai:{state:'idle',stagger:0,phase:1}};world={time:0,fxTime:0,player:{x:600,y:480,h:110},targets:[entity],enemyArt:assets.enemyArt};$('#load-notice').textContent='';}
 catch(error){if(current===token)$('#load-notice').textContent=error.message+'，点击妖兽重试。';}
}
function animate(now){const dt=Math.min(.05,(now-last)/1000);last=now;time+=dt;ctx.clearRect(0,0,680,600);ctx.save();const g=ctx.createRadialGradient(340,450,5,340,450,180);g.addColorStop(0,'#c0a05b20');g.addColorStop(1,'#5d7b8520');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(340,487,180,35,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b89d6460';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(340,487,165,28,0,0,Math.PI*2);ctx.stroke();ctx.restore();
 if(entity){const e=entity,d=ENEMIES[selected];world.time=world.fxTime=time;e.face=face;e.cycle=time*2;e.vx=motion==='walk'?90:0;e.ai.state=motion==='walk'?'walk':'idle';e.ai.attack=null;
  const plan=d.patterns.find(p=>p.kind===motion);if(plan){const total=plan.steps.reduce((a,s)=>a+s.windup+s.active+s.recover,0)+.8;let age=time%total,index=0;for(;index<plan.steps.length;index++){const s=plan.steps[index],length=s.windup+s.active+s.recover;if(age<length)break;age-=length;}if(index<plan.steps.length)e.ai.attack={plan,index,age,fired:age>=plan.steps[index].windup,aim:{x:520,y:480},victims:[]};}
  painter.unit(world,e,1);const a=e.ai.attack,s=a?.plan.steps[a.index];if(s&&a.age>=s.windup&&a.age<s.windup+s.active+.25)painter.effect(world,{kind:'enemyVfx',enemyKind:selected,style:s.style,x:e.x+face*100,y:e.y-100,face,radius:100,age:a.age-s.windup,duration:s.active+.25,melee:s.type==='melee'||s.type==='dash'});
 }
 requestAnimationFrame(animate);
}
$$('[data-kind]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.kind;choose(ENEMY_IDS.find(id=>ENEMIES[id].boss===(category==='boss')));}));$$('[data-motion]').forEach(b=>b.addEventListener('click',()=>{motion=b.dataset.motion;time=0;$$('[data-motion]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));$('#turn').addEventListener('click',()=>face*=-1);choose(selected);requestAnimationFrame(animate);

